<?php
namespace App\Services;
use App\Models\{Product,Upload,BusinessSetting};
use Illuminate\Support\Facades\{DB,Cache};
class ProductImageVersions {
 private static function image($path){$image=\Image::make($path);if(function_exists('exif_read_data')&&strtolower($image->mime())==='image/jpeg'){try{$image->orientate();}catch(\Throwable $ignored){}}return $image;}
 private static function key($id){return 'product_image_versions_v1_'.(int)$id;}
 private static function data($p){$row=BusinessSetting::where('type',self::key($p->id))->first();$data=$row?json_decode($row->value,true):null;return is_array($data)?$data:['original'=>(int)$p->thumbnail_img,'entries'=>[]];}
 private static function store($p,$data){$row=BusinessSetting::where('type',self::key($p->id))->first()?:new BusinessSetting();$row->type=self::key($p->id);$row->value=json_encode($data);$row->save();}
 private static function remember(&$data,$id,$label){if(!$id)return;if(!isset($data['entries'][(string)$id]))$data['entries'][(string)$id]=['id'=>(int)$id,'label'=>$label,'at'=>now()->toIso8601String()];}
 private static function path($u){$path=realpath(public_path($u->file_name));$root=realpath(public_path('uploads'));abort_unless($path&&$root&&strpos(str_replace('\\','/',$path),rtrim(str_replace('\\','/',$root),'/').'/')===0,422,'Local image required.');$size=@getimagesize($path);abort_unless($size&&$size[0]*$size[1]<=40000000,422,'Unsupported image.');return $path;}
 private static function clear($p){foreach(['products','products-category-'.$p->category_id,'todays_deal_products']as $key)Cache::forget($key);}
 public static function listing($id){$p=Product::findOrFail($id);$data=self::data($p);self::remember($data,$data['original'],'Original / প্রথম সংরক্ষিত');self::remember($data,$p->thumbnail_img,'Current / বর্তমান');$rows=[];foreach($data['entries']as $entry){$u=Upload::find($entry['id']);if(!$u)continue;$size=@getimagesize(public_path($u->file_name));$rows[]=array_merge($entry,['url'=>my_asset($u->file_name),'width'=>$size[0]??null,'height'=>$size[1]??null,'current'=>(string)$u->id===(string)$p->thumbnail_img,'original'=>(int)$u->id===$data['original']]);}return ['product_id'=>$p->id,'current'=>(int)$p->thumbnail_img,'versions'=>array_reverse($rows)];}
 public static function choose($id,$target,$expected){return DB::transaction(function()use($id,$target,$expected){$p=Product::where('id',$id)->lockForUpdate()->firstOrFail();abort_unless((string)$p->thumbnail_img===(string)$expected,409,'Thumbnail changed. Reopen versions.');$data=self::data($p);self::remember($data,$data['original'],'Original / প্রথম সংরক্ষিত');self::remember($data,$p->thumbnail_img,'Previous / আগের ছবি');abort_unless(isset($data['entries'][(string)$target]),422,'Choose a saved version for this product.');self::path(Upload::findOrFail($target));DB::table('products')->where('id',$id)->update(['thumbnail_img'=>(string)$target,'updated_at'=>now()]);self::store($p,$data);self::clear($p);return self::listing($id);});}
 private static function copy($u,$operation,$edge,$settings=[]){$path=self::path($u);$relative='uploads/products/versions/'.hash('sha256',hash_file('sha256',$path).':'.$operation.':hq95:'.$edge.':'.json_encode($settings)).'.jpg';$existing=Upload::where('file_name',$relative)->first();if($existing&&is_file(public_path($relative)))return $existing;
  $folder=dirname(public_path($relative));if(!is_dir($folder)&&!mkdir($folder,0755,true)&&!is_dir($folder))throw new \RuntimeException('Image folder unavailable.');$im=null;$canvas=null;try{$im=self::image($path);if($operation==='portrait'){$im->resize(450,600,function($c){$c->aspectRatio();});$canvas=\Image::canvas(450,600,'#ffffff')->insert($im,'center');}elseif($operation==='resize'){$im->resize($settings['width'],$settings['height'],function($c){$c->aspectRatio();});$canvas=\Image::canvas($settings['width'],$settings['height'],'#ffffff')->insert($im,'center');}elseif($operation==='enhance'){$im->brightness($settings['brightness'])->contrast($settings['contrast'])->sharpen($settings['sharpness']);}else{$im->resize($edge,$edge,function($c)use($operation){$c->aspectRatio();if($operation!=='600')$c->upsize();});$canvas=\Image::canvas($edge,$edge,'#ffffff')->insert($im,'center');}$out=$canvas?:$im;$temp=public_path($relative).'.'.bin2hex(random_bytes(4)).'.tmp';$out->save($temp,$operation==='enhance'?95:90,'jpg');if(!rename($temp,public_path($relative)))throw new \RuntimeException('Image write failed.');}finally{if($im)$im->destroy();if($canvas)$canvas->destroy();}
  $copy=$existing?:new Upload();$copy->file_name=$relative;$copy->file_original_name=$u->file_original_name.'-'.$operation;$copy->user_id=$u->user_id;$copy->type='image';$copy->extension='jpg';$copy->file_size=filesize(public_path($relative));$copy->save();OptimizedImages::buildUpload($copy->id,null,'manual');return $copy;
 }
 public static function convert($id,$expected,$mode){abort_unless(in_array($mode,['portrait','square','600'],true),422);$p=Product::findOrFail($id);abort_unless((string)$p->thumbnail_img===(string)$expected,409,'Thumbnail changed. Scan again.');$u=Upload::findOrFail($expected);$path=self::path($u);$size=getimagesize($path);$edge=$mode==='600'?600:min(600,max($size[0],$size[1]));$copy=self::copy($u,$mode,$edge);
  DB::transaction(function()use($id,$expected,$copy,$mode){$p=Product::where('id',$id)->lockForUpdate()->firstOrFail();abort_unless((string)$p->thumbnail_img===(string)$expected,409,'Thumbnail changed. Scan again.');$data=self::data($p);self::remember($data,$data['original'],'Original / প্রথম সংরক্ষিত');self::remember($data,$expected,'Previous / আগের ছবি');self::remember($data,$copy->id,$mode==='portrait'?'450×600 · 3:4 draft':($mode==='600'?'600×600 draft':'1:1 draft'));self::store($p,$data);DB::table('products')->where('id',$id)->update(['thumbnail_img'=>(string)$copy->id,'updated_at'=>now()]);self::clear($p);});return ImageOptimizationPanel::thumbnail(Product::findOrFail($id));
 }
 public static function resize($input){
  $id=$input['product_id'];$expected=$input['upload_id'];$p=Product::findOrFail($id);abort_unless((string)$p->thumbnail_img===(string)$expected,409,'Thumbnail changed. Refresh the list.');$u=Upload::findOrFail($expected);$source=self::image(self::path($u));$sw=$source->width();$sh=$source->height();$source->destroy();
  if($input['method']==='scale'){$factor=(int)$input['factor'];abort_unless(in_array($factor,[1,2,3],true),422,'Scale must be 1x, 2x or 3x.');$width=$sw*$factor;$height=$sh*$factor;}else{$width=(int)$input['width'];$height=(int)$input['height'];}
  abort_unless($width>=16&&$height>=16&&$width<=$sw*3&&$height<=$sh*3&&$width<=4096&&$height<=4096&&$width*$height<=12000000,422,'Resize is limited to 3x per side, 4096px per side and 12 megapixels.');
  $copy=self::copy($u,'resize',0,['width'=>$width,'height'=>$height]);
  DB::transaction(function()use($id,$expected,$copy,$width,$height){$p=Product::where('id',$id)->lockForUpdate()->firstOrFail();abort_unless((string)$p->thumbnail_img===(string)$expected,409,'Thumbnail changed. Refresh the list.');$data=self::data($p);self::remember($data,$data['original'],'Original / প্রথম সংরক্ষিত');self::remember($data,$expected,'Previous / আগের ছবি');self::remember($data,$copy->id,'Resize '.$width.'×'.$height.' draft');self::store($p,$data);DB::table('products')->where('id',$id)->update(['thumbnail_img'=>(string)$copy->id,'updated_at'=>now()]);self::clear($p);});
  return ImageOptimizationPanel::thumbnail(Product::findOrFail($id));
 }
 public static function enhance($input){$p=Product::findOrFail($input['product_id']);abort_unless((string)$p->thumbnail_img===(string)$input['upload_id'],409,'Thumbnail changed. Reopen versions.');$u=Upload::findOrFail($input['upload_id']);$copy=self::copy($u,'enhance',0,array_intersect_key($input,array_flip(['sharpness','brightness','contrast'])));
  DB::transaction(function()use($p,$copy,$input){$p=Product::where('id',$p->id)->lockForUpdate()->firstOrFail();abort_unless((string)$p->thumbnail_img===(string)$input['upload_id'],409,'Thumbnail changed. Reopen versions.');$data=self::data($p);self::remember($data,$data['original'],'Original / প্রথম সংরক্ষিত');self::remember($data,$p->thumbnail_img,'Previous / আগের ছবি');self::remember($data,$copy->id,'Enhanced draft / preview');self::store($p,$data);});return self::listing($p->id);
 }
}
